        // ── APPS LOAD ─────────────────────────────────────────────────────────
        private async Task LoadAppsInternalAsync()
        {
            if (_allApps.Count > 0) ApplyAppsView();

            ShowLoading(_LS("Apps", "Loading"));
            try
            {
                var fresh = await _appsService.GetInstalledAppsAsync();
                if (fresh.Count > 0) _allApps = fresh;
                MarkAppsWithNotes();
                ApplyAppExtras();
                ApplyAppsView();
                _ = EnrichAppsAsync();
            }
            finally { HideLoading(); }
        }

