        /// <summary>Enriches the service list with friendly descriptions from the dictionary.</summary>
        private static void EnrichServiceDescriptions(System.Collections.Generic.IEnumerable<WinServiceEntry> services)
        {
            foreach (var svc in services)
            {
                if (_serviceFriendlyDesc.TryGetValue(svc.Name, out var friendly))
                    svc.Description = friendly;
                // if not in the dictionary, keep the original WMI description
            }
        }

        private WinServiceEntry? SelectedService => ServicesGrid.SelectedItem as WinServiceEntry;

        private async void StartService_Click(object s, RoutedEventArgs e)
        {
            if (SelectedService == null) return;
            if (!ConfirmServiceChange("Start", SelectedService.DisplayName, SelectedService.Name)) return;
            ShowLoading(string.Format(_LS("Services", "StartingFmt"), SelectedService.DisplayName));
            try
            {
                bool ok = await _svcService.StartServiceAsync(SelectedService.Name);
                HideLoading();
                AppDialog.Show(ok ? _LS("Services", "Started") : _LS("Services", "StartFailed"), "SMD Win");
                await ReloadServicesAsync();
            }
            catch (Exception ex)
            {
                HideLoading();
                AppLogger.Warning(ex, "StartService_Click");
                AppDialog.Show(_LS("Services", "ModifyFailed"), "SMD Win");
            }
        }

        private async void StopService_Click(object s, RoutedEventArgs e)
        {
            if (SelectedService == null) return;
            if (!ConfirmServiceChange("Stop", SelectedService.DisplayName, SelectedService.Name)) return;
            ShowLoading(string.Format(_LS("Services", "StoppingFmt"), SelectedService.DisplayName));
            try
            {
                bool ok = await _svcService.StopServiceAsync(SelectedService.Name);
                HideLoading();
                AppDialog.Show(ok ? _LS("Services", "Stopped") : _LS("Services", "StopFailed"), "SMD Win");
                await ReloadServicesAsync();
            }
            catch (Exception ex)
            {
                HideLoading();
                AppLogger.Warning(ex, "StopService_Click");
                AppDialog.Show(_LS("Services", "ModifyFailed"), "SMD Win");
            }
        }

        /// <summary>Confirmation + log for any Windows service change.</summary>
        private bool ConfirmServiceChange(string action, string display, string name)
        {
            bool ok = AppDialog.Confirm($"{action} service \"{display}\" ({name})?\n\nThis changes how Windows runs. Critical services are refused automatically.", "Windows service");
            ToolActivityLog.Add("Services", $"{(ok ? "" : "Cancelled: ")}{action} {name}", ok ? "info" : "info");
            return ok;
        }

        private async void SetManual_Click(object s, RoutedEventArgs e) => await SetStartType("Manual");
        private async void DisableService_Click(object s, RoutedEventArgs e) => await SetStartType("Disabled");
        private async void SetAutomatic_Click(object s, RoutedEventArgs e) => await SetStartType("Automatic");

        private async Task SetStartType(string type)
        {
            if (SelectedService == null) { AppDialog.Show(_LS("Services", "SelectService")); return; }
            if (!ConfirmServiceChange("Set startup type to " + type + " for", SelectedService.DisplayName, SelectedService.Name)) return;
            try
            {
                bool ok = await _svcService.SetServiceStartTypeAsync(SelectedService.Name, type);
                AppDialog.Show(ok ? string.Format(_LS("Services", "StartTypeSetFmt"), type) : _LS("Services", "SetTypeError"), "SMD Win");
                await ReloadServicesAsync();
                RefreshServiceToggleLabels();
            }
            catch (Exception ex)
            {
                AppLogger.Warning(ex, "SetStartType");
                AppDialog.Show(_LS("Services", "ModifyFailed"), "SMD Win");
            }
        }

        // Quick service management
        private async void DisableWindowsUpdate_Click(object s, RoutedEventArgs e)
        {
            if (!ConfirmServiceChange("Stop and disable", "Windows Update", "wuauserv")) return;
            try
            {
                await _svcService.StopServiceAsync("wuauserv");
                await _svcService.SetServiceStartTypeAsync("wuauserv", "Disabled");
                AppDialog.Show(_LS("Services", "WuDisabled"), "SMD Win");
                await ReloadServicesAsync();
            }
            catch (Exception ex)
            {
                AppLogger.Warning(ex, "DisableWindowsUpdate_Click");
                AppDialog.Show(_LS("Services", "ModifyFailed"), "SMD Win");
            }
        }
        private async void EnableWindowsUpdate_Click(object s, RoutedEventArgs e)
        {
            if (!ConfirmServiceChange("Enable and start", "Windows Update", "wuauserv")) return;
            try
            {
                await _svcService.SetServiceStartTypeAsync("wuauserv", "Automatic");
                await _svcService.StartServiceAsync("wuauserv");
                AppDialog.Show(_LS("Services", "WuEnabled"), "SMD Win");
                await ReloadServicesAsync();
            }
            catch (Exception ex)
            {
                AppLogger.Warning(ex, "EnableWindowsUpdate_Click");
                AppDialog.Show(_LS("Services", "ModifyFailed"), "SMD Win");
            }
        }
