        private void OpenServicesMsc_Click(object s, RoutedEventArgs e)
        {
            System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("services.msc") { UseShellExecute = true });
        }

        // ── QUICK ACTIONS ─────────────────────────────────────────────────────

        private void WinCmd_Click(object sender, RoutedEventArgs e)
        {
            if (sender is not System.Windows.Controls.Button btn) return;
            string tag = btn.Tag?.ToString() ?? "";

            string cmd;
            switch (tag)
            {
                case "CHKDSK_PROMPT":
                    if (!AppDialog.Confirm(
                        _LS("Tools", "ChkdskConfirm"),
"Check Disk")) return;
                    cmd = "echo Y | chkdsk C: /f /r & echo. & echo Scheduled for next reboot. & pause";
                    break;

                case "WINSOCK_PROMPT":
                    if (!AppDialog.Confirm(
                        _LS("Tools", "WinsockResetConfirm"),
"Reset Winsock")) return;
                    cmd = "netsh winsock reset & echo. & echo Done. Reboot required. & pause";
                    break;

                case "TCPIP_PROMPT":
                    if (!AppDialog.Confirm(
                        _LS("Tools", "TcpIpResetConfirm"),
"Reset TCP/IP")) return;
                    cmd = "netsh int ip reset & echo. & echo Done. Reboot required. & pause";
                    break;

                case "ICONCACHE":
                    if (!AppDialog.Confirm(_LS("Tools", "IconCacheConfirm"), "Icon Cache")) return;
                    cmd = "taskkill /f /im explorer.exe & " +
"del /f /q \"%localappdata%\\IconCache.db\" & " +
"del /f /q \"%localappdata%\\Microsoft\\Windows\\Explorer\\iconcache*\" & " +
"start explorer.exe & " +
"echo. & echo Icon cache rebuilt. & pause";
                    break;

                case "CLEARTEMP":
                    if (!AppDialog.Confirm(_LS("Tools", "ClearTempConfirm"), "Clear Temp")) return;
                    cmd = "del /f /s /q \"%TEMP%\\*\" & " +
"del /f /s /q \"C:\\Windows\\Temp\\*\" & " +
"echo. & echo Temp files cleared. & pause";
                    break;

                default:
                    // SFC / DISM: long operations (10–30 min), confirmation with the estimated duration
                    if (tag.StartsWith("sfc", StringComparison.OrdinalIgnoreCase))
                    { if (!AppDialog.Confirm(_LS("Tools", "SfcConfirm"), "SFC")) return; }
                    else if (tag.StartsWith("DISM", StringComparison.OrdinalIgnoreCase))
                    { if (!AppDialog.Confirm(_LS("Tools", "DismConfirm"), "DISM")) return; }
                    cmd = tag;
                    break;
            }

            try
            {
                System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo
                {
                    FileName        = "cmd.exe",
                    Arguments       = $"/k {cmd}",
                    UseShellExecute = true,
                    Verb            = "runas", // run as admin for system commands
                });
                (string tool, string note) = tag switch
                {
                    "CHKDSK_PROMPT"  => ("Check disk", "scheduled for the next restart"),
                    "WINSOCK_PROMPT" => ("Reset Winsock", "done · restart needed"),
                    "TCPIP_PROMPT"   => ("Reset TCP/IP", "done · restart needed"),
                    "ICONCACHE"      => ("Rebuild icon cache", "Explorer restarted"),
                    "CLEARTEMP"      => ("Clear temporary files", "ran in a command window"),
                    _ when tag.StartsWith("sfc", StringComparison.OrdinalIgnoreCase)  => ("Check system files", "result in the command window"),
                    _ when tag.StartsWith("DISM", StringComparison.OrdinalIgnoreCase) => ("Repair Windows image", "result in the command window"),
                    _ => (tag, "ran in a command window"),
                };
                SMDWin.Services.ToolActivityLog.Add(tool, note, "info");
            }
            catch (Exception ex)
            {
                AppDialog.Show(string.Format(_LS("Tools", "CommandFailedFmt"), ex.Message),
"Error", AppDialog.Kind.Warning);
            }
        }
    }
}
